<style>
/* ============================================================
   RESET
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --sa: #4a8e32;          /* Rasenstreifen hell  */
  --sb: #2d6b1e;          /* Rasenstreifen dunkel */
  --w:  #ffffff;
  --w88: rgba(255,255,255,0.88);
  --w72: rgba(255,255,255,0.72);
  --w50: rgba(255,255,255,0.50);
  --w28: rgba(255,255,255,0.28);
  --red:  #e05040;
  --gold: #d4a830;
  --fm:   rgba(255,255,255,0.52);  /* Feldmarkierungs-Farbe */
}

html { font-size: 16px; scroll-behavior: smooth; }

/* ── DER GESAMTE HINTERGRUND: scrollende Rasenstreifen ── */
body {
  font-family: 'Aptos Light', 'Aptos', 'Segoe UI Light', 'Helvetica Neue', sans-serif;
  font-weight: 300;
  color: var(--w);
  background: repeating-linear-gradient(
    180deg,
    var(--sa) 0px,   var(--sa) 80px,
    var(--sb) 80px,  var(--sb) 160px
  );
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

/* Quarto wrapper: transparent lassen */
#quarto-content,
main.content,
.page-layout-full .content {
  padding: 0 !important;
  max-width: 100% !important;
  margin: 0 !important;
  background: transparent !important;
}

/* Quarto-Titelblock ausblenden */
#title-block-header,
.quarto-title-block,
.quarto-title-meta { display: none !important; }

h1, h2, h3, h4 {
  font-family: 'Aptos Light', 'Aptos', 'Segoe UI Light', 'Helvetica Neue', sans-serif;
  font-weight: 300;
  line-height: 1.18;
  color: var(--w);
  text-shadow: 0 2px 20px rgba(0,0,0,0.50);
}

p { margin-bottom: 1.1rem; }

code {
  background: rgba(255,255,255,0.13);
  padding: 0.1em 0.35em;
  border-radius: 2px;
  font-size: 0.88em;
}

/* ============================================================
   SPIELFELD-SVG – absolut, gesamte Dokumenthöhe, scrollend
   Proportionen: 68 m × 105 m (Breite × Länge)
   ============================================================ */
body { position: relative; }

#field-svg {
  position: absolute;
  top: 0; left: 0;
  width: 100%;
  pointer-events: none;
  z-index: 1;
}

/* Inhaltselemente explizit über das Feld-SVG */
.hero, .section-wrap, .field-line, .page-footer {
  position: relative;
  z-index: 2;
}

/* ============================================================
   HERO
   ============================================================ */
.hero {
  position: relative;
  min-height: 96vh;
  background: transparent;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 80px 32px 100px;
}

.hero-content { max-width: 840px; }

.hero-eyebrow {
  font-family: 'Aptos Light', 'Aptos', 'Segoe UI Light', sans-serif;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--w50);
  margin-bottom: 1.4rem;
}

.hero h1 {
  font-size: clamp(2.2rem, 5.5vw, 4.4rem);
  color: var(--w);
  margin-bottom: 1rem;
  font-style: italic;
  text-shadow: 0 2px 28px rgba(0,0,0,0.60), 0 1px 0 rgba(0,0,0,0.25);
  letter-spacing: -0.01em;
}

.hero-subtitle {
  font-family: 'Aptos Light', 'Aptos', 'Segoe UI Light', sans-serif;
