  margin-bottom: 1.6rem;
}

.story-text {
  font-family: 'Aptos Light', 'Aptos', 'Segoe UI Light', sans-serif;
  font-size: 1.03rem;
  line-height: 1.82;
  color: var(--w88);
  max-width: 700px;
  margin-bottom: 1.4rem;
  font-weight: 300;
}

/* Highlight-Box: kein Hintergrund, nur weisser Balken links */
.highlight-box {
  background: transparent;
  border-left: 4px solid var(--w50);
  padding: 1.1rem 1.5rem;
  margin: 1.8rem 0;
}

.highlight-box.red  { border-left-color: var(--red);  }
.highlight-box.gold { border-left-color: var(--gold); }

.highlight-box p {
  font-family: 'Aptos Light', 'Aptos', 'Segoe UI Light', sans-serif;
  font-size: 0.92rem;
  color: var(--w88);
  margin: 0;
  line-height: 1.65;
}

.highlight-box strong { color: var(--w); }

.chart-wrap {
  margin: 2.4rem 0 0.6rem;
  background: rgba(0,0,0,0.32);
  border-radius: 6px;
  padding: 10px 10px 4px;
}

.chart-caption {
  font-family: 'Aptos Light', 'Aptos', 'Segoe UI Light', sans-serif;
  font-size: 0.78rem;
  color: var(--w50);
  margin-top: 0.4rem;
  font-style: italic;
}

.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2.5rem;
  align-items: start;
  margin: 2rem 0;
}


/* Methodik */
.methodik-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  margin-top: 2.4rem;
}

.methodik-item {
  border-top: 2px solid var(--w28);
  padding-top: 0.9rem;
}

.methodik-item h4 {
  font-size: 0.88rem;
  font-family: 'Aptos Light', 'Aptos', 'Segoe UI Light', sans-serif;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: var(--w);
  text-shadow: none;
}

.methodik-item p {
  font-family: 'Aptos Light', 'Aptos', 'Segoe UI Light', sans-serif;
  font-size: 0.83rem;
  color: var(--w72);
  margin: 0;
  line-height: 1.6;
}

/* Plotly */
.cell-output-display { margin: 0; }
.plotly { overflow: visible !important; }

/* Footer */
.page-footer {
  background: transparent;
  border-top: 1px solid var(--w28);
  color: var(--w50);
  text-align: center;
  padding: 2.2rem;
  font-family: 'Aptos Light', 'Aptos', 'Segoe UI Light', sans-serif;
